column3:
[Meta]
Version=4

[BulletImpact]
Enabled={0}

[Debug]
; True = also write the per-frame DIAG lines to BulletImpact.log (hits, kill shots and crippling are always logged).
LogHits={1}

[Wounds]
; Shattered spine / pelvis / knee / leg bones put people down for good (they crawl), a broken neck
; paralyzes, a shattered foot leaves a limp. Decided from each hit's X-ray.
Crippling={2}
; Your weapon damage against everyone, 1.0 = vanilla. Lower = people soak more hits before dying.
PlayerDamage={3}
; A shot whose X-ray destroys the brain or pierces the heart kills outright, whatever the damage.
KillShots={4}

[XRay]
; X-ray log (F11, then Tab): the newest MaxEntries people and the newest MaxEntries animals are kept in enRAGE\xray_log.json.
MaxEntries={5}
; Detail: Auto (best that fits the rect limit) / High / Medium / Low.
Detail={6}
; The game's per-frame limit on script-drawn rects (it silently drops the rest). The X-ray uses
; whatever the menu leaves under it. Measure it with the calibration screen: K in the X-ray log.
RectLimit={7}
; Every letter of text on screen seems to come out of the same per-frame limit (the X-ray report's text left the skeleton
; half drawn). The X-ray budget takes this many units off per drawn letter. Raise it if bones still go missing.
GlyphCost={8}

column4:
[Meta]
Version=4

[BulletImpact]
Enabled={0}

[Debug]
; True = também grava as linhas DIAG de cada quadro no BulletImpact.log (acertos, tiros fatais e aleijamentos sempre vão pro log).
LogHits={1}

[Wounds]
; Coluna / pelve / joelho / ossos da perna estilhaçados derrubam a pessoa de vez (ela rasteja), pescoço quebrado
; paralisa, pé estilhaçado deixa mancando. Decidido pelo raio-X de cada acerto.
Crippling={2}
; O dano da sua arma contra todo mundo, 1.0 = original. Menor = as pessoas aguentam mais tiros antes de morrer.
PlayerDamage={3}
; Um tiro cujo raio-X destrói o cérebro ou perfura o coração mata na hora, seja qual for o dano.
KillShots={4}

[XRay]
; Registro de raio-X (F11, depois Tab): as MaxEntries pessoas mais recentes e os MaxEntries animais mais recentes ficam em enRAGE\xray_log.json.
MaxEntries={5}
; Detail: Auto (o melhor que cabe no limite de retângulos) / High / Medium / Low.
Detail={6}
; O limite por quadro do jogo para retângulos desenhados por script (ele descarta o resto sem avisar). O raio-X usa
; o que o menu deixar sobrando. Meça com a tela de calibração: K no registro de raio-X.
RectLimit={7}
; Cada letra de texto na tela parece sair do mesmo limite por quadro (o texto do relatório do raio-X deixava o esqueleto
; desenhado pela metade). O orçamento do raio-X desconta essa quantidade de unidades por letra desenhada. Aumente se ainda faltarem ossos.
GlyphCost={8}
